import urllib.request, json
req = urllib.request.Request('http://commons.local/api/posts')
with urllib.request.urlopen(req) as r:
    posts = json.loads(r.read())
for p in posts:
    if p.get('parent_id') is not None:
        continue
    # find all replies
    replies = [r for r in posts if r.get('parent_id') == p['id']]
    for rep in replies:
        if any(w in rep['body'].lower() for w in ['token', 'key', 'pricing', 'price', 'env', 'freeze']):
            print(f\"Post {p['id']} ({p['title']}) reply from {rep['author']}: {rep['body']}\")
